{
  "cvars": {
    "ivs": [
      {
        "description": "Primary independent variable: continuous masculinity-femininity index for hurricane names (higher = more feminine). This measures perceived femininity of a storm's name coded by independent raters. Primary test: higher femininity (masfem) is hypothesized to be associated with fewer precautions (proxied by more fatalities controlling for storm strength).",
        "columns": [
          "masfem",
          "z_masfem"
        ]
      }
    ],
    "dv": {
      "description": "Dependent variable: human impact of the storm, measured as total fatalities (count) and a logged version for OLS specifications. We use alldeaths for count models (Negative Binomial) and log_alldeaths for OLS robustness checks.",
      "columns": [
        "alldeaths",
        "log_alldeaths"
      ]
    },
    "controls": [
      {
        "description": "Storm physical severity controls: maximum sustained wind at landfall (mph).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "wind"
        ]
      },
      {
        "description": "Storm physical severity control: minimum central pressure at landfall (hPa) — lower values indicate stronger storms.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "min"
        ]
      },
      {
        "description": "Storm category on the Saffir-Simpson scale (1-5).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "category"
        ]
      },
      {
        "description": "Temporal control: year of the storm to account for secular trends in reporting, evacuation procedures, and population exposure.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "year"
        ]
      },
      {
        "description": "Years elapsed since the storm (used in original dataset as a covariate related to reporting/normalization).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "elapsedyrs"
        ]
      },
      {
        "description": "Source of data; included as a categorical fixed effect to control for systematic differences across sources.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "source"
        ]
      },
      {
        "description": "Alternative / auxiliary IV: MTurk-based femininity rating (same scale as masfem) used as a robustness check. Standardized version included.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "masfem_mturk",
          "z_masfem_mturk"
        ]
      },
      {
        "description": "Binary encoding of the original gender label (0 = male name, 1 = female name). Included as an alternative independent variable or control.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "gender_mf"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Work on a copy\n    df = df.copy()\n\n    # Ensure columns exist\n    required_cols = ['alldeaths', 'masfem', 'gender_mf', 'wind', 'min', 'category', 'year', 'elapsedyrs', 'source', 'masfem_mturk']\n    # Some columns may be missing in particular data exports; guard against KeyError by creating if absent\n    for col in required_cols:\n        if col not in df.columns:\n            df[col] = np.nan\n\n    # Convert source to category for use in formula-based models\n    df['source'] = df['source'].astype('category')\n\n    # Drop rows missing the core dependent or primary IV or key severity controls\n    df = df.dropna(subset=['alldeaths', 'masfem', 'wind', 'min', 'category'])\n\n    # Create logged fatalities for OLS/robustness (add 1 to keep zeros)\n    df['log_alldeaths'] = np.log(df['alldeaths'] + 1)\n\n    # Standardize the masfem measures (z-scores) to make coefficients comparable\n    df['z_masfem'] = (df['masfem'] - df['masfem'].mean()) / (df['masfem'].std(ddof=0) if df['masfem'].std(ddof=0) != 0 else 1)\n\n    # Also standardize the MTurk-based rating (used in robustness checks)\n    if df['masfem_mturk'].notna().sum() > 0:\n        df['z_masfem_mturk'] = (df['masfem_mturk'] - df['masfem_mturk'].mean()) / (df['masfem_mturk'].std(ddof=0) if df['masfem_mturk'].std(ddof=0) != 0 else 1)\n    else:\n        df['z_masfem_mturk'] = np.nan\n\n    # Ensure category, year, elapsedyrs are numeric\n    df['category'] = pd.to_numeric(df['category'], errors='coerce')\n    df['year'] = pd.to_numeric(df['year'], errors='coerce')\n    df['elapsedyrs'] = pd.to_numeric(df['elapsedyrs'], errors='coerce')\n\n    # Drop rows with missing values in controls after coercion\n    df = df.dropna(subset=['wind', 'min', 'category', 'year', 'elapsedyrs'])\n\n    # Keep the columns needed for modeling explicit and return\n    model_cols = ['alldeaths', 'log_alldeaths', 'masfem', 'z_masfem', 'masfem_mturk', 'z_masfem_mturk', 'gender_mf', 'wind', 'min', 'category', 'year', 'elapsedyrs', 'source']\n    # Some columns may not have been filled (masfem_mturk), but keep them in df so modeling code can handle NA appropriately\n    return df[model_cols].reset_index(drop=True)\n",
  "m_code": "def model(df: pd.DataFrame) -> dict:\n    import statsmodels.api as _sm\n    import statsmodels.formula.api as smf\n\n    results = {}\n\n    # Formula for primary specification: test whether name femininity predicts fatalities controlling for storm severity and time/source\n    # Negative binomial on counts (alldeaths) is appropriate for overdispersed count data.\n    nb_formula = 'alldeaths ~ z_masfem + gender_mf + wind + min + category + year + elapsedyrs + C(source)'\n\n    # Fit Negative Binomial (GLM). Use robust (HC3) covariances for inference.\n    try:\n        nb_model = smf.glm(nb_formula, data=df, family=_sm.families.NegativeBinomial()).fit(cov_type='HC3')\n        results['nb_primary'] = nb_model\n    except Exception as e:\n        results['nb_primary_error'] = str(e)\n\n    # OLS robustness: logged fatalities\n    ols_formula = 'log_alldeaths ~ z_masfem + gender_mf + wind + min + category + year + elapsedyrs + C(source)'\n    try:\n        ols_model = smf.ols(ols_formula, data=df).fit(cov_type='HC3')\n        results['ols_log_fatalities'] = ols_model\n    except Exception as e:\n        results['ols_error'] = str(e)\n\n    # Robustness: use MTurk-based femininity rating instead of masfem if available\n    if df['z_masfem_mturk'].notna().sum() > 0:\n        nb_formula_mturk = 'alldeaths ~ z_masfem_mturk + gender_mf + wind + min + category + year + elapsedyrs + C(source)'\n        try:\n            nb_model_mturk = smf.glm(nb_formula_mturk, data=df.dropna(subset=['z_masfem_mturk']), family=_sm.families.NegativeBinomial()).fit(cov_type='HC3')\n            results['nb_mturk'] = nb_model_mturk\n        except Exception as e:\n            results['nb_mturk_error'] = str(e)\n\n    # Additional diagnostic: simple tabulation of mean fatalities by gender_mf\n    try:\n        results['means_by_gender'] = df.groupby('gender_mf')['alldeaths'].agg(['count', 'mean', 'median']).to_dict()\n    except Exception:\n        results['means_by_gender'] = None\n\n    # Return fitted model result objects (statsmodels results). The caller can call .summary() on each result.\n    return results\n"
}
